program OptionExample;

uses Std.Console, Std.Conv, Std.Array, Std.Option;

function FindFirst(Items: array of integer; Min: integer): option of integer;
begin
  for I: integer := 0 to Length(Items) - 1 do
  begin
    if Items[I] >= Min then
    begin
      return Some(Items[I])
    end
  end;

  return None
end;

function DoubleFirst(Items: array of integer; Min: integer): option of string;
begin
  var V: integer := try FindFirst(Items, Min);
  return Some((IntToStr(V) + ' x 2 = ') + IntToStr(V * 2))
end;

begin
  var Data: array of integer := [3, 7, 15, 42, 8];
  var Found: option of integer := FindFirst(Data, 10);
  WriteLn('IsSome: ', IsSome(Found));
  WriteLn('Value: ', Unwrap(Found));
  var Missing: option of integer := FindFirst(Data, 100);
  WriteLn('IsNone: ', IsNone(Missing));
  WriteLn('UnwrapOr: ', UnwrapOr(Missing, 0));
  case FindFirst(Data, 40) of
    Some(V):
    begin
      WriteLn('Found >= 40: ', V)
    end;
    None:
    begin
      WriteLn('Nothing >= 40')
    end
  end;

  case FindFirst(Data, 100) of
    Some(V):
    begin
      WriteLn('Found >= 100: ', V)
    end;
    None:
    begin
      WriteLn('Nothing >= 100')
    end
  end;

  case DoubleFirst(Data, 10) of
    Some(S):
    begin
      WriteLn(S)
    end;
    None:
    begin
      WriteLn('No match to double')
    end
  end;

  case DoubleFirst(Data, 100) of
    Some(S):
    begin
      WriteLn(S)
    end;
    None:
    begin
      WriteLn('No match to double')
    end
  end
end.

program HigherOrderFunctionsExample;

uses Std.Console, Std.Array;

// First-class named functions

function Square(X: integer): integer;
begin
  return X * X
end;

function Double(X: integer): integer;
begin
  return X * 2
end;

function IsGreaterThanThree(X: integer): boolean;
begin
  return X > 3
end;

function IsGreaterThanTen(X: integer): boolean;
begin
  return X > 10
end;

function Sum(Acc: integer; V: integer): integer;
begin
  return Acc + V
end;

// Higher-order: accepts any integer->integer function

function Apply(F: function(X: integer): integer; Value: integer): integer;
begin
  return F(Value)
end;

begin
  WriteLn('Apply(Square, 6) = ', Apply(Square, 6));
  var Op: function(X: integer): integer := Double;
  WriteLn('Op(7) = ', Op(7));
  var Nums: array of integer := [1, 2, 3, 4, 5];
  var Doubled: array of integer := Map(Nums, Double);
  Write('Map double: ');
  for V: integer in Doubled do
  begin
    Write(V, ' ')
  end;

  WriteLn('');
  var Big: array of integer := Filter(Nums, IsGreaterThanThree);
  Write('Filter > 3: ');
  for V: integer in Big do
  begin
    Write(V, ' ')
  end;

  WriteLn('');
  var Total: integer := Reduce(Nums, 0, Sum);
  WriteLn('Reduce sum: ', Total);
  var Squared: array of integer := Map(Nums, Square);
  var LargeSquares: array of integer := Filter(Squared, IsGreaterThanTen);
  Write('Squares > 10: ');
  for V: integer in LargeSquares do
  begin
    Write(V, ' ')
  end;

  WriteLn('')
end.

